def solve(s: str) -> str:
    if not s:
        return ""

    result = []
    run_char = s[0]
    run_length = 1

    for char in s[1:]:
        if char == run_char:
            run_length += 1
        else:
            result.append(run_char + str(run_length))
            run_char = char
            run_length = 1

    result.append(run_char + str(run_length))
    return "".join(result)

def solve(s: str) -> bool:
    depth = 0
    for char in s:
        if char == '(':
            depth += 1
        elif char == ')':
            depth -= 1
            if depth < 0:
                return False
        else:
            return False
    return depth == 0

def solve(s: str) -> int:
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    previous = 0

    for symbol in reversed(s):
        value = values[symbol]
        if value < previous:
            total -= value
        else:
            total += value
            previous = value

    return total

def solve(nums: list) -> int:
    n = len(nums)
    return n * (n + 1) // 2 - sum(nums)

def solve(s: str) -> str:
    return ''.join(
        chr((ord(c) - ord('a') - 3) % 26 + ord('a')) if 'a' <= c <= 'z' else c
        for c in s
    )

def solve(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def solve(s: str) -> bool:
    normalized = "".join(char for char in s if char.isalnum()).casefold()
    return normalized == normalized[::-1]

def solve(tokens: list) -> int:
    stack = []
    for token in tokens:
        if token in ("+", "-", "*"):
            right = stack.pop()
            left = stack.pop()
            if token == "+":
                stack.append(left + right)
            elif token == "-":
                stack.append(left - right)
            else:
                stack.append(left * right)
        else:
            stack.append(int(token))
    return stack[-1]

import re

def solve(s: str) -> str:
    return re.sub(r"\S+", lambda match: match.group(0).capitalize(), s)

from collections import Counter

def solve(s: str) -> str:
    counts = Counter(s)
    max_count = max(counts.values())
    return min(char for char, count in counts.items() if count == max_count)

def solve(n: int) -> int:
    while n >= 10:
        n = sum(int(digit) for digit in str(n))
    return n

def solve(s: str) -> str:
    result = []
    for char in s:
        if not result or char != result[-1]:
            result.append(char)
    return "".join(result)
